-- =============================================================================
--  WezTerm — Catppuccin Mocha
--  Generated by ~/.config/terminal-theme/install.sh
-- =============================================================================

local config = wezterm.config_builder()

-- --- Font --------------------------------------------------------------------
config.font = wezterm.font_with_fallback({
  '@FONT@',
  'FiraCode Nerd Font',
  'Noto Color Emoji',
})

-- --- Colours -----------------------------------------------------------------
config.color_scheme = 'Catppuccin Mocha'

-- Explicit palette so the scheme works without the official colour file.
config.colors = {
  foreground = '@FG@',
  background = '@BG@',
  cursor_bg = '@CURSOR@',
  cursor_border = '@CURSOR@',
  cursor_fg = '@BG@',
  selection_bg = '@SELECT_BG@',
  selection_fg = '@SELECT_FG@',

  ansi = {
    '@BLACK@', '@RED@', '@GREEN@', '@YELLOW@',
    '@BLUE@', '@MAGENTA@', '@CYAN@', '@WHITE@',
  },
  brights = {
    '@BR_BLACK@', '@RED@', '@GREEN@', '@YELLOW@',
    '@BLUE@', '@MAGENTA@', '@CYAN@', '@BR_WHITE@',
  },
}

-- --- Appearance --------------------------------------------------------------
config.window_background_opacity = 0.94
config.window_padding = { left = 8, right = 8, top = 6, bottom = 6 }
config.window_decorations = 'RESIZE'
config.enable_tab_bar = true
config.tab_bar_at_bottom = false
config.tab_title = '%1f%{1..1}%n'

config.cursor_shape = 'Block'
config.cursor_blink_rate = 0.5
config.cursor_style = 'Steady'

config.scrollback_lines = 100000
config.use_fancy_tab_bar = true
config.fancy_tab_bar_icons = false

-- --- Key bindings ------------------------------------------------------------
config.keys = {
  {
    key = 'Left',
    mods = 'CTRL|SHIFT',
    action = wezterm.action_callback(function(_, pane)
      if pane:search('\r$') then
        pane:search('\r', 'HistoryForward')
      else
        pane:search('\r', 'HistoryBackward')
      end
    end),
  },
  {
    key = 'Right',
    mods = 'CTRL|SHIFT',
    action = wezterm.action_callback(function(_, pane)
      if pane:search('\r$') then
        pane:search('\r', 'HistoryForward')
      else
        pane:search('\r', 'HistoryBackward')
      end
    end),
  },
}

return config
